@namespace sv_44e5cdcde3e747e3b15c549babc2f0ff.Components.Pages.Settings
@using sv_44e5cdcde3e747e3b15c549babc2f0ff.Services

<div class="settings-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <!-- Theme -->
        <div class="form-group">
            <label><strong>Theme</strong></label>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="theme" value="Light" checked="@(_theme == "Light")" @onchange="() => _theme = \"Light\"" />
                    <span>Light</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")" @onchange="() => _theme = \"Dark\"" />
                    <span>Dark</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="System" checked="@(_theme == "System")" @onchange="() => _theme = \"System\"" />
                    <span>System</span>
                </label>
            </div>
        </div>

        <!-- Font Size -->
        <div class="form-group">
            <label><strong>Font Size</strong></label>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Small" checked="@(_fontSize == "Small")" @onchange="() => _fontSize = \"Small\"" />
                    <span>Small</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Medium" checked="@(_fontSize == "Medium")" @onchange="() => _fontSize = \"Medium\"" />
                    <span>Medium</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Large" checked="@(_fontSize == "Large")" @onchange="() => _fontSize = \"Large\"" />
                    <span>Large</span>
                </label>
            </div>
        </div>

        <!-- Language -->
        <div class="form-group">
            <label for="language"><strong>Language</strong></label>
            <select id="language" @bind="_language" class="form-control">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
                <option value="Chinese">Chinese</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="form-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_compactMode" />
                <span><strong>Compact Mode</strong></span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <h4>Live Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <p>Theme: @_theme | Font: @_fontSize | Language: @_language</p>
            <button class="btn btn-primary">Sample Button</button>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="toast-message success">@_message</div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private string _message = "";

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLower()} preview-font-{_fontSize.ToLower()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance saved!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _message = "";
        StateHasChanged();
    }
}

@page "/settings"
@namespace sv_44e5cdcde3e747e3b15c549babc2f0ff.Components.Pages.Settings
@using sv_44e5cdcde3e747e3b15c549babc2f0ff.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-page">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection SettingsService="SettingsService" />
                break;
            case "Notifications":
                <NotificationsSection SettingsService="SettingsService" />
                break;
            case "Security":
                <SecuritySection SettingsService="SettingsService" />
                break;
            case "Appearance":
                <AppearanceSection SettingsService="SettingsService" />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

arguments.file_text:
.settings-page {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.sidebar-title {
    padding: 0 1.5rem;
    margin: 0 0 1rem;
    font-size: 1.25rem;
    color: #333;
}

.sidebar-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background 0.15s, border-left 0.15s;
    border-left: 3px solid transparent;
    color: #555;
}

.sidebar-item:hover {
    background: #e9ecef;
}

.sidebar-item.active {
    background: #e3f2fd;
    border-left-color: #1976d2;
    color: #1976d2;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Content Area */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

